"// Declare Variables
const target = arguments[0];
let goalX = 0;
let goalY = 0;

// Calculations
//enemyX = BattleManager._targets[0].screenX();
let enemyX = $target.battler().x;
let actorX = $subject.battler().x;
if (enemyX < actorX){
    goalX = enemyX * 10;
    goalY = 0;
    //console.log("left");
}else{
    goalX = enemyX;
    goalY = 0;
    //console.log("right");
}
//console.log(goalX, actorX);

// Return Data
return new Point(goalX, goalY);"

